"""Verify complete native conversion and five source roles before scoped bigWig catalog credit."""
import hashlib
import json
from pathlib import PurePosixPath
import stat
import zipfile
from catalog_source_integrity import verify_source
from catalog_fixed_cohort import verify_fixed_cohort


def sha(raw):return hashlib.sha256(raw).hexdigest()


def verify(root,data):
    folder=root/'docs/literature/bigwig-typed-workflow';proof=json.loads((folder/'VALIDATION.json').read_bytes());assert proof['schema_version']==1 and proof['status']=='passed-public-native-bigWig-captured-workflows-and-portable-verification';sums=dict(line.split('  ',1)[::-1] for line in (folder/'SHA256SUMS').read_text().splitlines());assert set(sums)=={'controls.zip','VALIDATION.json'}
    for name,digest in sums.items():assert sha((folder/name).read_bytes())==digest
    archive=folder/'controls.zip';assert archive.stat().st_size==proof['archive']['bytes'] and sha(archive.read_bytes())==proof['archive']['sha256']
    with zipfile.ZipFile(archive) as z:
        assert z.testzip() is None and len(z.infolist())==len(set(z.namelist()))==len(proof['archive_files'])==proof['archive']['entries']
        for entry in z.infolist():
            name=entry.filename;member=PurePosixPath(name);assert not member.is_absolute() and '..' not in member.parts and '\\' not in name and stat.S_IFMT(entry.external_attr>>16)==stat.S_IFREG;raw=z.read(name);value=proof['archive_files'][name];assert len(raw)==value['bytes'] and sha(raw)==value['sha256']
        for name,value in proof['source_pins'].items():
            raw=z.read('source/'+name);assert len(raw)==value['bytes'] and sha(raw)==value['sha256'];verify_source(root,data,name,value['sha256'])
    assert proof['exact_source_classes']==25 and len(proof['new_classes'])==15 and proof['changed_classes']==['org/jlinalg/cli/JLinAlgCli.class'];assert sorted(r['name'] for r in proof['platform_validation'])==['linux-java21','windows-java21','windows-java25'] and all(r['tests']==r['passed']==74 and r['skipped']==0 and r['public_workflows']==44 for r in proof['platform_validation']);assert (proof['packaged_public_workflows'],proof['complete_packaged_intervals'],proof['portable_complete_bundle_verifications'],proof['actual_main_example_fits'],proof['actual_main_example_verifications'])==(132,479688,396,6,6)
    assert len(proof['actual_malformed_metadata_rejections'])==2 and all(r['process']['exit_code']==2 for r in proof['actual_malformed_metadata_rejections']);assert len(proof['actual_permission_skips']['cases'])==2 and all(r['exit_code']==3 and r['uid']==65534 for r in proof['actual_permission_skips']['cases']);assert proof['public_workflow_available'] and proof['historical_malformed_admission_explicitly_invalidated'] and not any(proof[k] for k in ['implementation_credit','released','pushed','deployed','whole_goal_complete','original_UCSC_and_pyBigWig_dependency_required_for_conversion'])
    native=root/'docs/literature/bigwig-native-development';old=json.loads((native/'VALIDATION.json').read_bytes());link=proof['original_reference_linkage'];assert sha((native/'VALIDATION.json').read_bytes())==link['native_checkpoint']['sha256'] and sha((native/'controls.zip').read_bytes())==link['native_archive']['sha256'];assert old['native_protocols']==22 and old['complete_native_intervals']==79948 and old['successful_original_converter_protocols']==20 and link['public_track_bytes_exact_originally_read_native_reference'] and not link['new_UCSC_or_pyBigWig_runs_claimed']
    artifact=root/proof['artifact']['path']
    if artifact.exists():assert artifact.stat().st_size==proof['artifact']['bytes'] and sha(artifact.read_bytes())==proof['artifact']['sha256']
    roles=json.loads((data/'bigwig-role-coverage.json').read_bytes());assert roles['applied'] and roles['source_papers_scanned']==250 and roles['registry_rows']==425 and roles['reviewed_roles']==5 and roles['new_reviews']==4 and roles['prior_reviews_preserved']==815 and roles['total_reviews']==819 and roles['supporting_pointers']==248 and roles['existing_role_P163_unchanged'] and not roles['implementation_promoted'];verify_source(root,data,'tools/literature/reviewed-uses.json',roles['reviews_sha256']);assert sha((root/'tools/literature/curate_bigwig_uses.py').read_bytes())==roles['curator_sha256'] and sha((root/'tools/literature/bigwig-use-reviews.json').read_bytes())==roles['draft_sha256']
    papers=json.loads((data/'papers.json').read_bytes());verify_fixed_cohort(root,data,papers);observed={p['paper_id']:p for p in papers if any(t['tool_id']=='ucsc-bedgraphtobigwig' for t in p['tools'])};assert set(observed)=={r['paper_id'] for r in roles['source_proof']}=={'P013','P050','P110','P138','P163'};reviews=json.loads((root/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];selected=[r for r in reviews if r['tool_id']=='ucsc-bedgraphtobigwig'];assert len(selected)==5
    for row in roles['source_proof']:
        paper=observed[row['paper_id']];tool=next(t for t in paper['tools'] if t['tool_id']=='ucsc-bedgraphtobigwig');review=next(r for r in selected if r['pmcid']==paper['pmcid']);assert paper['doi']==row['doi'] and paper['xml_sha256']==row['xml_sha256'] and tool['evidence_paragraph_sha256']==row['paragraph_sha256']==review['evidence_paragraph_sha256'] and tool['use_summary']==review['use_summary'] and tool['implementation_scope_note']==review['implementation_scope_note']
    assert next(t for t in observed['P110']['tools'] if t['tool_id']=='ucsc-bedgraphtobigwig')['version_reported_near_name']=='v4'
    return proof


def bigwig_metadata(root,data):
    proof=verify(root,data)
    return dict(implementation_status='native-subset-validated',implementation_source='src/main/java/org/jlinalg/genetics/BigWigWriter.java',coverage_note='Native Java implements the supplied local bedGraph-to-indexed-bigWig role. Original converter summary/zoom/historical-edition identity is not claimed.',implementation_scope='Native bigwig-tools converts complete plain or strict concatenated-gzip bedGraph plus explicit local chromosome sizes to bigWig v4. Every raw input, decimal/float64/float32 precision disposition and declared/stored/omitted reference row is retained. Explicit exact-literal or rounding, used/all dictionary and zlib/uncompressed policies; unsigned32 coordinates, no aliases/clipping/overlap averaging/normalization or missing-zero filling. Complete chromosome/R-tree indexes and raw data are audited; native double total summaries differ from UCSC float arithmetic and no zoom approximations are written. Whole captured bundles verify on Windows/Linux without opening producer paths. No external tool/Python installation is needed. Read BIGWIG_WORKFLOW.md and examples/bigwig/README.md; upstream signal creation, unknown historical editions/resources, downstream consumer behavior and complete paper pipelines remain separate.',validation_note='74 actual-JAR tests each Windows Java21/25 and Linux Java21 without skips, strict exact-source25-class match, unchanged native writer and unrelated parent entries. Three JVMs run132 public workflows reusing22 synthetic reference protocols in plain/gzip form (479688 interval instances); every track matches its independently read native prototype byte for byte. Earlier original readers cover79948 interval instances across22 protocols; this phase claims byte linkage, not new original-tool runs. All396 complete producer/consumer portable verifications and six actual-main examples/verifies pass. Actual nonprivileged input/output permission skips and malformed metadata rejections pass. Original nonfinite summaries, a pinned Cygwin reader crash/signed coordinate view and converter failures remain visible; no biological or historical-pipeline certificate.',project_native_available=True,canonical_adapter_available=False,development_native_cli='bigwig-tools',development_candidate=proof['artifact']['path'],development_candidate_sha256=proof['artifact']['sha256'])


BIGWIG_WARNING='''## Native bigWig conversion: precision, reference and recovery

**Current-source bigwig-tools is available; older canonical/released JARs lack it.** Read BIGWIG_WORKFLOW.md, bigwig-typed-workflow/VALIDATION.json and examples/bigwig/README.md. Native Java converts and verifies complete local plain/gzip input without an external UCSC/Python runtime or installation. Declare exact build/units, float32 exact|round, dictionary used|all and compression zlib|none. No assembly/resource inference, normalization, clipping, aliases, overlap averaging or missing-zero filling occurs.

**PRECISION LOSS IS EXPLICIT.** Exact policy compares the original decimal to stored float32, including information lost in float64. Round permits loss and reports every value in VALUE-LEDGER.tsv, with exact float64/float32 hex, bits and underflow stage. REFERENCE-LEDGER.tsv retains every declared chromosome and stored/omitted disposition. Empty tracks require all-reference policy and are not measured zero signal. Metadata/control lines are counted and retained; malformed coordinate-bearing track/browser rows are rejected.

**NATIVE TOTAL SUMMARIES DIFFER; NO ZOOM APPROXIMATIONS ARE WRITTEN.** Raw data/indexes remain complete. Native compensated double summaries differ from UCSC2.10 float arithmetic; original finite raw signals can create infinite original summaries. A retained pinned Cygwin pyBigWig header crash, signed-coordinate views above2^31 and original converter failures remain explicit. Verify the intended downstream consumer and large-range performance; original summary bits, zoom statistics and historical converter identity are not claimed. P110 reports literal v4 with release-versus-format ambiguity; do not infer converter2.10.

**SKIP3: required input/output access forbidden means skip the dependent conversion. FAIL2: input, precision, integrity, capacity, I/O, cancellation or finalization failure admits no result.** Read WARNINGS.md, FAILURE.json and its named stage, request.json, INPUT-AUDIT.json, OUTPUT-AUDIT.json and both complete TSV ledgers. Preserve partials, correct the cause and use NEW paths. Require overall COMPLETED.json, no INCOMPLETE.json/FAILURE.json, and successful --verify. Complete input/decoded/record/line/output/workspace limits are explicit; requested output capacity and16MiB final metadata reserve must fit beside prepared evidence. Limits are not JVM heap guarantees. Copied bundles verify without reading producer paths; hashes establish integrity, not authenticity or biology. Cell Ranger remains excluded.
'''

